{$ param image_url label="Image URL" default="https://picsum.photos/800/400" description="Card image." type="fileurl" $}
{$ param image_alt label="Image Alt" default="" description="Accessibility description." $}
{$ param title label="Project Title" default="Project Name" description="Title shown in the card." $}
{$ param href label="Project URL" default="#" description="Where the title and button link to." $}
{$ param time_tag label="Time Tag" default="" description="E.g. '15 min' (leave blank to hide)." $}
{$ param location_tag label="Location Tag" default="" description="E.g. 'Outdoors' (leave blank to hide)." $}
{$ param cta_label label="CTA Label" default="Learn More" description="Button label." $}

<div class="ss-pc mb-4">
  <div class="ss-pc-img">
    <img src="{$= image_url $}" alt="{$= image_alt $}" />
  </div>
  <div class="ss-pc-content">
    <h3><a href="{$= href $}">{$= title $}</a></h3>
    {$ slot description $}
      <p>Short project description.</p>
    {$ /slot $}
    {$ if time_tag $}<div class="ss-pc-tag-wrap">
      <div class="ss-pc-tag"><span>{$= time_tag $}</span></div>
      {$ if location_tag $}<div class="ss-pc-tag"><span>{$= location_tag $}</span></div>{$ /if $}
    </div>{$ /if $}
    <a href="{$= href $}" class="btn btn-primary">{$= cta_label $}</a>
  </div>
</div>
